Hi All,<div><br></div><div>I&#39;ve come across my least favourite error: &#39;<i>Error: Failed to Create Shared Library&#39; </i>and am hoping there is someone out there who may be able to help me! As far as I&#39;m aware there is nothing wrong with my C++ compiler, because I can compile multiple other stuff (including other nimbleFunctions). But for some reason, this particular model isn&#39;t working. And it&#39;s not just my computer either, I&#39;ve tried it on a second machine and get the same results, so I&#39;m wondering if it&#39;s something in the model?</div><div><br></div><div>Here&#39;s the code: </div><div>####################### SET UP #########################</div><div>library(dplyr)<br>library(lubridate)<br>library(nimble)<br><br>##Parameter values<br>theta &lt;- c(<br>  a  = 0.015,<br>  e  = 100,<br>  r  = 0.05,<br>  p = 0.3<br>)<br>num.days &lt;- 500<br>tau &lt;- 1<br><br>##Initial conditions (Susceptible, Infected, Bacteria, New Infections)<br>N        = 10000<br>Io0       = 3<br>Ih0       = 7<br>B0       = 1000<br>S0       = N - Io0 - Ih0<br>z.init   = c(S = S0, Io = Io0, Ih = Ih0, B = B0, NI = 0)<br><br>traj &lt;- etl_codeco_nim(theta,z.init,num.days) #Z<br>monthly.cases &lt;- traj_2_data(traj)[[1]]<br>month.days.mapper &lt;- traj_2_data(traj)[[2]]<br>days.in.month &lt;- month.days.mapper[,2]<br>num.months &lt;- length(days.in.month)<br><br>################### NIMBLE MODEL ###############################<br>sequential.model &lt;- nimbleCode({<br>  z[1,1:5] &lt;- traj_end_month(theta[1:4], z.init[1:5], days.in.month[1])<br>  y[1] ~ dpois(z[1,5])<br>  for(i in 2:n){ #n is number of months<br>    z[i,1:5] &lt;- traj_end_month(theta[1:4], z[(i-1),1:5], days.in.month[i])<br>    y[i] ~ dpois(z[(i-1),5])<br>  }<br>  #Priors<br>  theta[1] ~ T(dnorm(0,5),0,)  # dgamma(3,0.6)        # a<br>  theta[2] ~ T(dnorm(0,5),0,)  # dgamma(10,1)         # e<br>  theta[3] ~ T(dnorm(0,5),0,)  # dgamma(3, 0.06)      # r<br>  theta[4] ~ T(dnorm(0,0.3),0,)                       # p<br>})<br><br>Consts      &lt;- list(n      = num.months - 1)<br>Data        &lt;- list(y      = monthly.cases,<br>                    z.init = z.init,<br>                    days.in.month = days.in.month)<br>inits       &lt;- list(theta  = theta) ## You will need this to calculate() returning -Inf when size=0 when y&gt;0<br>nimble.model &lt;- nimbleModel(code=sequential.model, constants = Consts, data = Data, inits = inits)<br><br>nimble.model.c &lt;- compileNimble(nimble.model)<br><br><br><br>############  FUNCTIONS ###########################<br>etl_codeco_nim &lt;- nimbleFunction(<br>  run = function(theta = double(1), z.init = integer(1), num.days = integer()){<br>    #State transition matrix (S,I_observed,I_hidden,Bacteria,New observed infection)<br>    nu &lt;- nimMatrix(c(0,0,-1,-1,0,0,<br>                      0,0,1,0,-1,0,<br>                      0,0,0,1,0,-1,<br>                      1,-1,0,0,0,0,<br>                      0,0,1,0,0,0),ncol = 5)<br>    <br>    time &lt;- seq(0,num.days,1)<br>    ##Monte Carlo Trajectory<br>    traj &lt;- matrix(nrow = length(time), ncol = length(z.init))<br>    traj[1,] &lt;- z.init<br>    #colnames(traj) &lt;- c(names(z.init))<br>    for(i in 2:length(time)){<br>      z &lt;- traj[(i-1),]<br>      #Event rates<br>      R &lt;- c((z[2]+z[3])*theta[2],                                            # Bacteria Birth  <br>             z[4]*0.1,                                                              # Bacteria death<br>             theta[1]  * (z[4] / (z[4] + 10**6)) * z[1] * theta[4],         # Observed Infection<br>             theta[1]  * (z[4] / (z[4] + 10**6)) * z[1] * (1-theta[4]),     # Hidden Infection<br>             theta[3]  *  z[2],                                                  # Observed Infective recovery<br>             theta[3]  *  z[3])                                                  # Hidden Infective recovery<br>      lambda &lt;- 1 * R<br>      k &lt;- rpois(length(lambda),lambda)<br>      knu &lt;- nimMatrix(value = 0, nrow = dim(nu)[1], ncol = dim(nu)[2])<br>      for(a in 1:length(k)){<br>        for(b in 1:dim(nu)[2]){<br>          knu[a,b] &lt;- nu[a,b] * k[a]<br>        }<br>      }<br>      changes &lt;- numeric(length = length(z.init))<br>      for(j in 1:length(changes)){<br>        changes[j] &lt;- sum(knu[,j])<br>      }<br>      <br>      traj[i,] &lt;- traj[(i-1),] +  changes<br>      traj[i,][traj[i,] &lt; 0] &lt;- 0<br>    }<br>    returnType(double(2))<br>    #return(traj[-1,])<br>    return(traj[2:(num.days+1),])<br>  })<br><br>##Convert daily infection simulation to monthly dataset<br>traj_2_data &lt;- function(traj, start.date = &quot;2000/01/01&quot;){<br>  traj.monthly &lt;- data.frame(traj) %&gt;%<br>    magrittr::set_colnames(c(&quot;S&quot;,&quot;Io&quot;,&quot;Ih&quot;,&quot;B&quot;,&quot;NI&quot;)) %&gt;%<br>    mutate(time = 1:nrow(traj)) %&gt;%<br>    mutate(date = as.Date(time, origin = start.date)) %&gt;%<br>    mutate(month = lubridate::month(date)) %&gt;%<br>    mutate(year = lubridate::year(date)) %&gt;%<br>    mutate(month.abs = month + 12*(year-2000)) %&gt;%<br>    mutate(days.in.month = days_in_month(date))<br>  month.final.day &lt;- traj.monthly[!duplicated(traj.monthly$month.abs,fromLast = TRUE),]<br>  month.days.mapper &lt;- month.final.day %&gt;% dplyr::select(month.abs, days.in.month,time)<br>  monthly.cases &lt;- rpois(n = nrow(month.final.day),lambda = month.final.day$NI) #Assuming case ascertainment rate = 30%<br>  return(list(monthly.cases, month.days.mapper))<br>}<br><br>traj_end_month &lt;- nimbleFunction(<br>  run = function(theta = double(1), z.init = integer(1), days.in.month = integer(0)){<br>    traj.month.i &lt;- etl_codeco_nim(theta,z.init,num.days = days.in.month)<br>    traj.end.month &lt;- traj.month.i[days.in.month,]<br>    <br>    returnType(double(1))<br>    return(traj.end.month)<br>  })<br></div><div><br></div><div>And here&#39;s the error report:</div><div>&gt; printErrors()
